function handler(input) {
  const { approve_item } = input;
  const fallbackFields = {
    '品类名称': '实际发放物料品类',
    '产品型号名称': '实际发放产品型号',
    '语种名称': '实际发放语种',
  };
  let base_item = input.base_item;
  const fallbackField = fallbackFields[approve_item.name];
  const baseItemMissing =
    base_item === undefined ||
    base_item === null ||
    base_item === '' ||
    (Array.isArray(base_item) && base_item.length === 0);
  if (baseItemMissing && fallbackField) {
    base_item = input.valueMap?.[fallbackField];
  }
  const new_item = {
    id: approve_item.id,
    type: approve_item.type,
    value: null,
  };

  function parseTextValue(
    value
  ) {
    if (
      value === undefined ||
      value === null
    ) {
      return '';
    }

    if (
      typeof value ===
        'string' ||
      typeof value ===
        'number' ||
      typeof value ===
        'boolean'
    ) {
      return String(value);
    }

    if (
      Array.isArray(value)
    ) {
      return value
        .map((item) => {
          if (
            item ===
              undefined ||
            item === null
          ) {
            return '';
          }
          if (
            typeof item !==
            'object'
          ) {
            return String(
              item
            );
          }
          return parseTextValue(
            item.text ??
              item.name ??
              item.value ??
              ''
          );
        })
        .join('');
    }

    if (
      typeof value ===
      'object'
    ) {
      return parseTextValue(
        value.text ??
          value.name ??
          value.value ??
          value.link ??
          ''
      );
    }

    return String(value);
  }

  function parseDocument(
    value
  ) {
    if (
      !value ||
      !value.link
    ) {
      return null;
    }
    const match = String(
      value.link
    ).match(
      /\/docx\/([^?]+)/
    );
    return match
      ? {
          token: match[1],
          type: 'docx',
        }
      : null;
  }

  function parseDateValue(
    value
  ) {
    const timestamp =
      Number(value);
    if (
      !Number.isFinite(
        timestamp
      )
    ) {
      return null;
    }
    return (
      new Date(
        timestamp +
          8 * 3600000
      )
        .toISOString()
        .substring(0, 19) +
      '+08:00'
    );
  }

  function parseDateIntervalValue(
    startTime,
    endTime
  ) {
    if (
      startTime ===
        undefined ||
      startTime === null ||
      endTime === undefined ||
      endTime === null
    ) {
      return null;
    }

    return {
      start: parseDateValue(
        startTime
      ),
      end: parseDateValue(
        endTime
      ),
      interval: Math.floor(
        (Number(endTime) -
          Number(startTime)) /
          (24 * 3600 * 1000)
      ),
    };
  }

  function parseUser(value) {
    const users =
      Array.isArray(value)
        ? value
        : [value];
    return users
      .map((item) => {
        if (
          typeof item ===
          'string'
        ) {
          return item;
        }
        return (
          item?.open_id ??
          item?.id ??
          ''
        );
      })
      .filter(Boolean);
  }

  function parseOptionValue(
    value,
    options
  ) {
    const optionText =
      parseTextValue(value);
    const matchedOption = (
      options || []
    ).find(
      (item) =>
        String(item.text) ===
        optionText
    );
    return matchedOption
      ? matchedOption.value
      : optionText;
  }

  function parseDepartment(
    value
  ) {
    const departments =
      Array.isArray(value)
        ? value
        : [value];
    return departments
      .map((item) => {
        if (
          typeof item ===
            'string' &&
          item.startsWith(
            'od-'
          )
        ) {
          return item;
        }
        if (
          item &&
          typeof item ===
            'object'
        ) {
          return (
            item.open_department_id ??
            item.open_id ??
            item.id ??
            ''
          );
        }
        return '';
      })
      .filter(Boolean)
      .map(
        (
          openDepartmentId
        ) => ({
          open_id:
            openDepartmentId,
        })
      );
  }

  switch (approve_item.type) {
    case 'input':
    case 'textarea':
      if (
        base_item !==
          undefined &&
        base_item !== null
      ) {
        new_item.value =
          parseTextValue(
            base_item
          );
      }
      break;

    case 'document': {
      const documentValue =
        parseDocument(
          base_item
        );
      if (documentValue) {
        new_item.value =
          documentValue;
      }
      break;
    }

    case 'text':
      break;

    case 'number':
      if (
        base_item !==
          undefined &&
        base_item !== null
      ) {
        const numberValue =
          Number(
            typeof base_item ===
              'object'
              ? base_item.value
              : base_item
          );
        if (
          Number.isFinite(
            numberValue
          )
        ) {
          new_item.value =
            numberValue;
        }
      }
      break;

    case 'amount':
      if (
        base_item !==
          undefined &&
        base_item !== null
      ) {
        const amountValue =
          Number(
            typeof base_item ===
              'object'
              ? base_item.value
              : base_item
          );
        if (
          Number.isFinite(
            amountValue
          )
        ) {
          new_item.value =
            amountValue;
        }
      }
      break;

    case 'date': {
      const dateValue =
        parseDateValue(
          base_item
        );
      if (dateValue) {
        new_item.value =
          dateValue;
      }
      break;
    }

    case 'department': {
      const departmentValue =
        parseDepartment(
          base_item
        );
      if (
        departmentValue.length ===
        0
      ) {
        throw new Error(
          '部门字段需要传入 open_department_id，当前值：' +
            parseTextValue(
              base_item
            )
        );
      }
      new_item.value =
        departmentValue;
      break;
    }

    case 'contact':
      if (
        base_item !==
          undefined &&
        base_item !== null
      ) {
        new_item.open_ids =
          parseUser(
            base_item
          );
      }
      break;

    case 'telephone':
      if (
        base_item !==
          undefined &&
        base_item !== null
      ) {
        new_item.value = {
          countryCode: '+86',
          nationalNumber:
            parseTextValue(
              base_item
            ),
        };
      }
      break;

    case 'radio':
    case 'radioV2':
      if (
        base_item !==
          undefined &&
        base_item !== null
      ) {
        new_item.value =
          parseOptionValue(
            base_item,
            approve_item.option
          );
      }
      break;

    case 'checkbox':
    case 'checkboxV2':
      if (
        base_item !==
          undefined &&
        base_item !== null
      ) {
        const selectedValues =
          Array.isArray(
            base_item
          )
            ? base_item
            : [base_item];
        new_item.value =
          selectedValues.map(
            (item) =>
              parseOptionValue(
                item,
                approve_item.option
              )
          );
      }
      break;

    case 'dateInterval':
      new_item.value =
        parseDateIntervalValue(
          input.valueMap?.[
            approve_item
              .begin_date
          ],
          input.valueMap?.[
            approve_item
              .end_date
          ]
        );
      break;

    default:
      if (
        base_item !==
          undefined &&
        base_item !== null
      ) {
        new_item.value =
          parseTextValue(
            base_item
          );
      }
      break;
  }

  return new_item;
}

function handler(input) {
  const {
    approve_item,
    base_item,
  } = input;
  const new_item = {
    id: approve_item.id,
    type: approve_item.type,
    value: null,
  };

  // 解析文本类型value
  function parseTextValue(
    value
  ) {
    if (
      value === undefined ||
      value === null
    ) {
      return '';
    }

    if (
      typeof value === 'string' ||
      typeof value === 'number' ||
      typeof value === 'boolean'
    ) {
      return String(value);
    }

    if (
      value.link
    ) {
      return value.link;
    }

    if (
      Array.isArray(value)
    ) {
      return value
        .map((item) => {
          if (
            item === undefined ||
            item === null
          ) {
            return '';
          }
          if (
            typeof item === 'string' ||
            typeof item === 'number' ||
            typeof item === 'boolean'
          ) {
            return String(item);
          }
          return (
            item.text ??
            item.name ??
            item.value ??
            ''
          );
        })
        .join('');
    }

    if (
      typeof value === 'object'
    ) {
      return (
        value.text ??
        value.name ??
        value.value ??
        ''
      );
    }

    return String(value);
  }

  function parseDocument(
    value
  ) {
    const match_docx =
      value.link.match(
        /\/docx\/([^?]+)/
      );
    let result = {};
    if (match_docx) {
      result['token'] =
        match_docx[1];
      result['type'] = 'docx';
    }
    return result;
  }

  // 解析日期类型value
  function parseDateValue(
    value
  ) {
    let date = new Date(
      value + 3600000 * 8
    );
    return (
      date
        .toISOString()
        .substring(0, 19) +
      '+08:00'
    );
  }

  // 解析日期区间类型的value
  function parseDateIntervalValue(
    startTime,
    endTime
  ) {
    if (
      startTime ===
        undefined ||
      startTime === null ||
      endTime === undefined ||
      endTime === null
    ) {
      return null;
    }
    var dateIntervalValue = {
      start: parseDateValue(
        startTime
      ),
      end: parseDateValue(
        endTime
      ),
      interval: Math.floor(
        (endTime -
          startTime) /
          (24 * 3600 * 1000)
      ),
    };
    return dateIntervalValue;
  }

  // 解析用户类型value
  function parseUser(value) {
    if (
      Array.isArray(value)
    ) {
      return value.map(
        function (
          item,
          index,
          arr
        ) {
          return item.id;
        }
      );
    }
    return [value.id];
  }

  // 解析电话类型value
  function parsePhone(value) {
    let v = {
      countryCode: '+86',
      nationalNumber:
        String(value),
    };
    return v;
  }

  // 解析选项类型value
  function parseOptionsValue(
    value,
    options
  ) {
    let result =
      'option not found by ' +
      value;
    options.some(function (
      item
    ) {
      if (
        item.text ==
        String(value)
      ) {
        result = item.value;
        return true;
      }
    });
    return result;
  }

  switch (approve_item.type) {
    case 'input':
    case 'textarea':
      if (
        base_item ==
          undefined ||
        base_item === null
      ) {
        break;
      }
      new_item.value =
        parseTextValue(
          base_item
        );
      break;
    case 'document':
      if (
        base_item ==
          undefined ||
        base_item === null
      ) {
        break;
      }
      if (
        Object.keys(
          parseDocument(
            base_item
          )
        ).length > 0
      ) {
        new_item.value =
          parseDocument(
            base_item
          );
      }
      break;
    case 'text':
      break;
    case 'number':
      if (
        base_item ==
          undefined ||
        base_item === null
      ) {
        break;
      }
      const value = Number(
        base_item
      );
      new_item.value = !isNaN(
        value
      )
        ? value
        : Number(
            base_item.value
          );
      break;
    case 'amount':
      // not support
      break;
    case 'date':
      if (
        base_item ==
          undefined ||
        base_item === null
      ) {
        break;
      }
      new_item.value =
        parseDateValue(
          base_item
        );
      break;
    case 'contact':
      if (
        base_item ==
          undefined ||
        base_item === null
      ) {
        break;
      }
      new_item.open_ids =
        parseUser(base_item);
      break;
    case 'telephone':
      // not support
      break;
    case 'radio':
    case 'radioV2':
      if (
        base_item ==
          undefined ||
        base_item === null
      ) {
        break;
      }
      new_item.value =
        parseOptionsValue(
          base_item,
          approve_item.option
        );
      break;
    case 'checkbox':
    case 'checkboxV2':
      if (
        base_item ==
          undefined ||
        base_item === null
      ) {
        break;
      }
      new_item.value =
        base_item.map(
          function (item) {
            return parseOptionsValue(
              item,
              approve_item.option
            );
          }
        );
      break;
    case 'dateInterval':
      new_item.value =
        parseDateIntervalValue(
          input.valueMap[
            approve_item
              .begin_date
          ],
          input.valueMap[
            approve_item
              .end_date
          ]
        );
      break;
    default:
      if (
        base_item ==
          undefined ||
        base_item === null
      ) {
        break;
      }
      new_item.value =
        parseTextValue(
          base_item
        );
      break;
  }

  return new_item;
}
